local formatTableModule = require(script.Parent.Parent.formatTable)
local formatTable = formatTableModule.formatTable

return function(plasma)
	local create = plasma.create
	return plasma.widget(function(debugger, object, operation)
		local custom = debugger._customWidgets
		local style = plasma.useStyle()
		local world = debugger.debugWorld
		local wk = debugger.Wukong

		local path = object.value:GetPath()
		path = path .. "?" .. operation.i.object.Name
		local closed = plasma
			.window({
				title = operation.t,
				closable = true,
				maxSize = Vector2.new(400, style.panelHeight)
			}, function()
				local paraNames, paraTypes = object.value:GetParameters(operation.i.object)
				local paras = {}
				for i, v in pairs(paraNames) do
					paras[i] = {
						text = v,
						selected = false,
						object = v
					}
				end
				local refs = plasma.useInstance(function(ref)
					return create("Frame", {
						BackgroundTransparency = 1,
						BackgroundColor3 = Color3.new(.2, .2, .2),
						AutomaticSize = Enum.AutomaticSize.Y,
						Size = UDim2.new(0, 290, 0, 0),

						create("UIListLayout", {
							HorizontalAlignment = Enum.HorizontalAlignment.Center,
							VerticalAlignment = Enum.VerticalAlignment.Center,
							FillDirection = Enum.FillDirection.Vertical,
							Padding = UDim.new(0, 10),
							SortOrder = Enum.SortOrder.LayoutOrder
						}),
						
						create("TextLabel", {
							[ref] = "label",
							BackgroundTransparency = 1,
							Text = operation.i.object.Name,
							AutomaticSize = Enum.AutomaticSize.Y,
							Font = Enum.Font.GothamBold,
							TextSize = 22,
							TextStrokeTransparency = 1,
							TextXAlignment = Enum.TextXAlignment.Center,
							TextYAlignment = Enum.TextYAlignment.Center,
							TextWrapped = true,
							TextColor3 = Color3.new(1, 1, 1),
							Size = UDim2.new(1, 0, 0, 50),
							LayoutOrder = 0,
							create("UIPadding", {
								PaddingBottom = UDim.new(0, 8),
								PaddingLeft = UDim.new(0, 8),
								PaddingRight = UDim.new(0, 8),
								PaddingTop = UDim.new(0, 8),
							}),
							create("UICorner")
						}),
					})
					
				end)
				local inputs = custom.paraList(paras, paraTypes)
				
				-- plasma.button("Excute")
				if custom.button1("Submit", {width = 100, bg = style.bg3}):clicked() then
					spawn(function()
						local suc, res, info, resTable = object.value:Execute(operation, path, inputs)
						if suc then
							if not res or res == "" then
								debugger.ExecuteRes = "\n".. info .. "\n"
								print("\n".. info .. "\n", resTable or res)
							else
								debugger.ExecuteRes = "\n".. info .. "\n".. res .. "\n"
								print("\n".. info .. "\n", resTable or res)
							end
						else
							debugger.ExecuteRes = "\n".. info .. "\n" .. tostring(res) .. "\n"
							print("\n".. info .. "\n", resTable or tostring(res))
						end
					end)
				end

				if debugger.ExecuteRes then
					custom.label1(debugger.ExecuteRes, {
						TextXAlignment = Enum.TextXAlignment.Center,
						Size = UDim2.fromScale(1, 0),
						AutomaticSize = Enum.AutomaticSize.Y,
						TextWrapped = true,
					})
				end
				
				refs.label.Text = operation.i.object.Name
			end)
			:closed()
		if closed then
			return closed
		end
		return nil
	end)
end
